arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

// Load data with Churned as string, then map "Yes" → true
var rawData = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(dataPath, hasHeader: true, separatorChar: ',');

var mappingPipeline = mlContext.Transforms.CustomMapping<CustomerDataRaw, ChurnedMapping>(
    (input, output) => output.Label = string.Equals(input.ChurnedText, "Yes", StringComparison.OrdinalIgnoreCase),
    contractName: "ChurnMapping");

var mappedData = mappingPipeline.Fit(rawData).Transform(rawData);

var split = mlContext.Data.TrainTestSplit(mappedData, testFraction: 0.2, seed: 42);

// Build pipeline: encode Region, combine features, train classifier
var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age),
        nameof(CustomerDataRaw.Income),
        nameof(CustomerDataRaw.PurchaseHistory),
        "RegionEncoded"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label",
        featureColumnName: "Features"));

// Train
var model = pipeline.Fit(split.TrainSet);

// Evaluate — guard against tiny test sets with no positive class
var predictions = model.Transform(split.TestSet);
try
{
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
catch (ArgumentOutOfRangeException)
{
    Console.WriteLine("Model trained — test set too small for reliable metrics. Add more data for proper evaluation.");
}

// Save model and register pooled prediction engine
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");

// Build a full pipeline that includes the label mapping for prediction
var fullPipeline = mappingPipeline.Append(pipeline);
var fullModel = fullPipeline.Fit(rawData);
mlContext.Model.Save(fullModel, rawData.Schema, modelPath);

builder.Services.AddPredictionEnginePool<CustomerDataRaw, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with { age, income, region, purchaseHistory }");

app.MapPost("/predict", (CustomerInput input, PredictionEnginePool<CustomerDataRaw, ChurnPrediction> pool) =>
{
    var data = new CustomerDataRaw
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory
    };
    var result = pool.Predict(data);
    return Results.Ok(new
    {
        WillChurn = result.PredictedLabel,
        Confidence = result.Probability
    });
});

app.Run();

// --- Data models ---

public class CustomerDataRaw
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = string.Empty;
