arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

// Load data
var rawData = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" string to boolean Label using built-in ValueMapping
var lookupKeys = new[] { "Yes", "No" };
var lookupValues = new[] { true, false };

var labelMapping = mlContext.Transforms.Conversion.MapValue(
    "Label", new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false },
    inputColumnName: nameof(CustomerData.ChurnedText));

var split = mlContext.Data.TrainTestSplit(rawData, testFraction: 0.2, seed: 42);

// Full pipeline: map label, encode Region, combine features, train
var pipeline = labelMapping
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        nameof(CustomerData.PurchaseHistory),
        "RegionEncoded"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label",
        featureColumnName: "Features"));

// Train
var model = pipeline.Fit(split.TrainSet);

// Evaluate — guard against tiny test sets
var predictions = model.Transform(split.TestSet);
try
{
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
catch (ArgumentOutOfRangeException)
{
    Console.WriteLine("Model trained — test set too small for reliable metrics. Add more data for proper evaluation.");
}

// Save and register pooled prediction engine
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
var fullModel = pipeline.Fit(rawData);
mlContext.Model.Save(fullModel, rawData.Schema, modelPath);

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with { age, income, region, purchaseHistory }");

app.MapPost("/predict", (CustomerInput input, PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var data = new CustomerData
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory
    };
    var result = pool.Predict(data);
    return Results.Ok(new
    {
        WillChurn = result.PredictedLabel,
        Confidence = result.Probability
    });
});

app.Run();

// --- Data models ---

public class CustomerData
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = string.Empty;
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4), ColumnName("ChurnedText")]
    public string ChurnedText { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

public record CustomerInput(float Age, float Income, string Region, float PurchaseHistory);

